  ('Dumbbell Upright Row', 'db-upright-row', 'shoulders', 'dumbbell', 'weight_reps', 'bilateral', null, array['back', 'biceps'], 'vertical_pull', 'Pulling the dumbbells straight up the front of the body with the elbows leading, for the shoulders and traps.', array['Stand tall with the dumbbells in front of your thighs, palms facing you.', 'Keep the dumbbells close together and close to your body.']::text[], array['Pull the dumbbells up toward your chest, leading with your elbows.', 'Stop when your elbows reach shoulder height.', 'Lower them slowly back to your thighs.']::text[], array['Pulling higher than shoulder height, which can pinch the shoulders.', 'Letting the wrists lead instead of the elbows.', 'Leaning back to heave the weight.']::text[], array['db upright row']::text[]),
  ('Dumbbell Y-Raise', 'db-y-raise', 'shoulders', 'dumbbell', 'weight_reps', 'bilateral', null, array['back'], 'raise', 'Raising light dumbbells overhead in a Y shape while face-down on an incline, for the lower traps and shoulders.', array['Lie face-down on a bench set to about 30 degrees, holding light dumbbells below your shoulders.', 'Turn your thumbs up toward the ceiling.']::text[], array['Raise your arms forward and out to make a Y with your body, thumbs up.', 'Lift until your arms are in line with your body.', 'Lower slowly back below your shoulders.']::text[], array['Using weights too heavy to reach full height.', 'Shrugging the shoulders up toward the ears.', 'Lifting the chest off the bench.']::text[], array['incline y raise', 'y raise', 'prone y raise']::text[]),
