  ('Standing Dumbbell Bicep Curl', 'db-curl', 'biceps', 'dumbbell', 'weight_reps', 'bilateral', null, array['forearms'], 'curl', 'Curling both dumbbells up with the palms facing up, the staple biceps exercise.', array['Stand tall with a dumbbell in each hand, arms straight and palms facing forward.', 'Keep your elbows close to your sides.']::text[], array['Curl the dumbbells up toward your shoulders, keeping your elbows still.', 'Squeeze your biceps at the top.', 'Lower slowly until your arms are straight again.']::text[], array['Swinging the body to lift the weight.', 'Letting the elbows move forward at the top.', 'Cutting the lowering phase short.']::text[], array['Dumbbell Curl', 'dumbbell bicep curl', 'db curl', 'biceps curl']::text[]),
  ('Alternating Dumbbell Curl', 'db-alternating-curl', 'biceps', 'dumbbell', 'weight_reps', 'bilateral', null, array['forearms'], 'curl', 'Curling one dumbbell at a time, turning the palm up as it rises.', array['Stand tall with the dumbbells at your sides, palms facing in.', 'Keep your elbows close to your body.']::text[], array['Curl one dumbbell up, turning your palm to face up as it rises.', 'Lower it slowly, then curl the other arm.', 'Keep alternating; each arm counts as one rep.']::text[], array['Rocking the body from side to side.', 'Rushing the lowering of one arm to start the other.', 'Not turning the palm up fully.']::text[], array['alternate dumbbell curl', 'alternating bicep curl']::text[]),
